// MIRROR of ConcurrentOrderedDictRandomizedConcurrencyTests.cs for ConcurrentOrderedCompactDict — the two types share one public surface and one
// thread-safety contract, so the sibling's gates run against this type verbatim (generated by substituting the
// type name; keep the two files in step when a scenario is added to either).
#nullable enable

using System;
using System.Collections.Concurrent;
using System.Collections.Generic;
using System.Linq;
using System.Threading;
using Microsoft.VisualStudio.TestTools.UnitTesting;
using NumSharp.Collections;

namespace NumSharp.Tests.Collections
{
    /// <summary>
    ///     Golden-standard, heavy-duty randomized concurrency stress for <see cref="ConcurrentOrderedCompactDict{TKey,TValue}" />.
    ///     Where the other two suites fire STRUCTURED storms (each thread plays one fixed role — appender, updater,
    ///     reader — and the gun is capped at the core count), every scenario here combines the WHOLE operation
    ///     surface chosen at random by every thread, all at once, under a gun of <b>16 or more</b> oversubscribed
    ///     threads. Two of the four tests carry an EXACT oracle: each thread owns a disjoint key partition and
    ///     mirrors it into a plain sequential <see cref="Dictionary{TKey,TValue}" /> — the trusted reference
    ///     implementation — so the concurrent collection can be checked for LINEARIZABILITY (agreement with the
    ///     sequential spec) after every single operation and, at quiescent barrier points, as a whole. The other two
    ///     hammer a SHARED key space with the full random surface and assert the interleaving-independent
    ///     invariants: the key-encoded value law on single-snapshot surfaces, structural self-consistency, and the
    ///     absence of any crash, deadlock, torn read, or cross-key contamination.
    /// </summary>
    /// <remarks>
    ///     <para>
    ///         The value law is the backbone of every check: a value legally stored under <c>key</c> is always
    ///         <see cref="Law" /><c>(key, generation)</c>, which folds the key into the high bits, so ANY (key, value)
    ///         a reader observes is self-verifying without knowing the interleaving — a value that decodes to a
    ///         different (or out-of-range) key is a torn read or a cross-key bleed, full stop.
    ///     </para>
    ///     <para>
    ///         Three contract boundaries are honored so the assertions are falsifiable rather than flaky:
    ///         (1) <see cref="ConcurrentOrderedCompactDict{TKey,TValue}.TryRemoveSwapBack" /> may transiently expose a
    ///         mixed key/value at the swapped slot, so the EXACT pair law is asserted on live surfaces only in the
    ///         swap-back-free scenario and otherwise only at true quiescence; (2) an index-addressed value write
    ///         (<c>SetAt</c> / the int-index setter) cannot preserve a key-encoded law under concurrent reindexing
    ///         — the slot's key is a moving target — so it is excluded from the law scenarios (its atomic store path
    ///         is already covered by the torn-read hunts in the base suite); (3) no callback (a RemoveWhere
    ///         predicate, an AddRange source, a GetOrAdd/AddOrUpdate factory) mutates the collection, so the enforced
    ///         reentrancy guard is never (falsely) tripped. No timing is asserted anywhere — only correctness.
    ///     </para>
    /// </remarks>
    [TestClass]
    public class ConcurrentOrderedCompactDictRandomizedConcurrencyTests
    {
        /// <summary>
        ///     Heavy gun width: at least 16 threads (the floor this suite promises), and a little more on a big box,
        ///     but capped at 24. The collection serializes EVERY mutation on one lock, so past ~16 threads more
        ///     shooters add only lock-convoy overhead, never throughput — 16 already saturate the write path — and an
        ///     unbounded oversubscription starves individual threads badly enough to trip the hang detector. The
        ///     contention is therefore held maximal while the TOTAL serialized-write budget of each scenario (not the
        ///     thread count) is what is kept bounded so the gun always drains within the join ceiling.
        /// </summary>
        private static int HeavyThreads => System.Math.Max(16, System.Math.Min(Environment.ProcessorCount, 24));

        /// <summary>
        ///     The concurrency gun (identical protocol to the sibling suites): arm <paramref name="threads" /> threads,
        ///     wait until every one is parked on the shared gate, release them all with a single signal so the
        ///     contended first microseconds are actually exercised, join them under a generous hang-detection ceiling,
        ///     and rethrow anything any of them threw so no failure is swallowed.
        /// </summary>
        /// <param name="threads">How many shooters to arm.</param>
        /// <param name="body">Per-thread workload; receives the 0-based thread id for partitioning.</param>
        /// <exception cref="AssertFailedException">A shooter failed to finish within the hang-detection ceiling (a deadlock/livelock guard, never a perf bound).</exception>
        /// <exception cref="AggregateException">One or more shooter bodies threw; carries every captured exception.</exception>
        private static void FireGun(int threads, Action<int> body)
        {
            using var go = new ManualResetEventSlim(false);
            using var ready = new CountdownEvent(threads);
            var errors = new ConcurrentQueue<Exception>();

            var shooters = new Thread[threads];
            for (int t = 0; t < threads; t++)
            {
                int id = t; // capture per-thread, not the loop variable
                shooters[t] = new Thread(() =>
                {
                    ready.Signal();
                    go.Wait();
                    try
                    {
                        body(id);
                    }
                    catch (Exception ex)
                    {
                        errors.Enqueue(ex);
                    }
                })
                {
                    IsBackground = true,
                    Name = $"cocd-rand-{t}",
                };
                shooters[t].Start();
            }

            ready.Wait();
            go.Set(); // fire: every thread leaves the gate in the same instant

            foreach (Thread s in shooters)
            {
                Assert.IsTrue(s.Join(TimeSpan.FromMinutes(2)), $"{s.Name} did not finish — deadlock or livelock");
            }

            if (!errors.IsEmpty)
            {
                throw new AggregateException(errors);
            }
        }

        /// <summary>The shared value law: a value legally stored under <paramref name="key" /> encodes the key in its high bits, so any (key, value) observation is self-checking without knowing the interleaving.</summary>
        /// <param name="key">The key the value belongs to (must be non-negative and below 2^43 so the shift stays positive).</param>
        /// <param name="generation">A churn counter folded into the low 20 bits; it need not be unique — the law only pins the key.</param>
        /// <returns>The encoded legal value.</returns>
        private static long Law(int key, int generation) => ((long)key << 20) | (uint)(generation & 0xFFFFF);

        /// <summary>Extracts the key a law-encoded value claims to belong to.</summary>
        /// <param name="value">A value produced by <see cref="Law" />.</param>
        /// <returns>The encoded key.</returns>
        private static int LawKey(long value) => (int)(value >> 20);

        /// <summary>Quiescent full audit shared by the scenarios: key↔index round-trip and both value paths agree at every position. Must be called only when no writer is running.</summary>
        /// <typeparam name="TKey">The dictionary's key type.</typeparam>
        /// <typeparam name="TValue">The dictionary's value type.</typeparam>
        /// <param name="d">The instance to audit.</param>
        private static void AssertFullyConsistent<TKey, TValue>(ConcurrentOrderedCompactDict<TKey, TValue> d)
            where TKey : notnull
        {
            int n = d.Count;
            for (int i = 0; i < n; i++)
            {
                TKey k = d.GetKeyAt(i);
                Assert.AreEqual(i, d.IndexOf(k), $"IndexOf(GetKeyAt({i})) must round-trip");
                Assert.IsTrue(d.TryGetValue(k, out TValue byKey));
                Assert.IsTrue(d.TryGetAt(i, out TValue byIndex));
                Assert.AreEqual(byKey, byIndex, $"key path and list path disagree at {i}");
            }
        }

        // ==========================================================================================================
        // 1. The golden oracle: per-partition linearizability against a sequential Dictionary reference.
        // ==========================================================================================================

        [TestMethod]
        public void Gun_RandomizedKeyOwnedOps_LinearizableAgainstSequentialMirror()
        {
            // GOLDEN-STANDARD linearizability oracle. Each of HeavyThreads (>= 16) threads OWNS a disjoint key
            // partition, so — although every thread hammers the ONE shared structure simultaneously — the per-key
            // state of a partition is determined solely by its owner's program-ordered sequence of key-addressed
            // operations. That lets each thread mirror its partition into a plain sequential Dictionary<int,long>
            // (the trusted reference) and assert, AFTER EVERY SINGLE OPERATION, that the concurrent collection
            // agrees with the reference EXACTLY: TryAdd's winner bit, the stored/returned value, the removed value,
            // and membership on BOTH the key path and the index path. A single lost write, resurrected key, torn
            // value, or cross-key bleed breaks the equality on the very next probe.
            //
            // TryRemoveSwapBack is deliberately INCLUDED: removing an owned key only relocates some OTHER
            // partition's tail entry (changing that key's index, never its membership or value), which is exactly
            // why the reference tracks membership+value and never index — and why a swap-back that corrupted the
            // moved entry's value would be caught by ITS owner's next per-op probe. Index-addressed writes
            // (SetAt / RemoveAt / RemoveWhere / Clear) are excluded: they touch keys this thread does not own, so
            // no per-partition reference can predict them (they get their own shared-space scenarios below).
            const int KeysPerThread = 1_000;
            const int OpsPerThread = 6_000;
            int threads = HeavyThreads;

            var d = new ConcurrentOrderedCompactDict<int, long>();

            // Pre-seed each partition half full (even keys) so removes/updates/CAS have live targets from op 1.
            for (int id = 0; id < threads; id++)
            {
                int lo = id * KeysPerThread;
                for (int k = lo; k < lo + KeysPerThread; k += 2)
                {
                    d.Add(k, Law(k, 0));
                }
            }

            var mirrors = new Dictionary<int, long>[threads];

            FireGun(threads, id =>
            {
                int lo = id * KeysPerThread;
                var mine = new Dictionary<int, long>();
                for (int k = lo; k < lo + KeysPerThread; k += 2)
                {
                    mine[k] = Law(k, 0); // mirror the seed
                }

                var rng = new System.Random(9_000 + id);
                int gen = 1;

                for (int op = 0; op < OpsPerThread; op++)
                {
                    int k = lo + rng.Next(KeysPerThread);
                    long nv = Law(k, gen++);
                    bool present = mine.TryGetValue(k, out long cur); // the reference's verdict BEFORE the op

                    switch (rng.Next(12))
                    {
                        case 0: // TryAdd: wins iff the key is absent
                        {
                            bool added = d.TryAdd(k, nv);
                            Assert.AreEqual(!present, added, $"TryAdd winner bit disagrees with the reference for key {k}");
                            if (added)
                            {
                                mine[k] = nv;
                            }

                            break;
                        }

                        case 1: // Add: succeeds iff absent, throws the duplicate-key ArgumentException iff present
                        {
                            if (present)
                            {
                                Assert.ThrowsExactly<ArgumentException>(() => d.Add(k, nv), $"Add must reject the duplicate key {k}");
                            }
                            else
                            {
                                d.Add(k, nv);
                                mine[k] = nv;
                            }

                            break;
                        }

                        case 2: // SetByKey: upsert, always leaves the key present with nv
                            d.SetByKey(k, nv);
                            mine[k] = nv;
                            break;

                        case 3: // GetOrAdd(value): returns the existing value or adds nv
                        {
                            long got = d.GetOrAdd(k, nv);
                            Assert.AreEqual(present ? cur : nv, got, $"GetOrAdd returned a non-winner for key {k}");
                            if (!present)
                            {
                                mine[k] = nv;
                            }

                            break;
                        }

                        case 4: // GetOrAdd(factory): same contract, factory path
                        {
                            long got = d.GetOrAdd(k, _ => nv);
                            Assert.AreEqual(present ? cur : nv, got, $"GetOrAdd(factory) returned a non-winner for key {k}");
                            if (!present)
                            {
                                mine[k] = nv;
                            }

                            break;
                        }

                        case 5: // AddOrUpdate: add nv if absent, else replace with nv — either way the key holds nv
                        {
                            long got = d.AddOrUpdate(k, nv, (_, __) => nv);
                            Assert.AreEqual(nv, got, $"AddOrUpdate returned the wrong post-value for key {k}");
                            mine[k] = nv;
                            break;
                        }

                        case 6: // TryUpdate with the matching comparand: succeeds iff present (nobody else writes this key)
                        {
                            bool ok = d.TryUpdate(k, nv, present ? cur : 0);
                            Assert.AreEqual(present, ok, $"TryUpdate CAS outcome disagrees with the reference for key {k}");
                            if (ok)
                            {
                                mine[k] = nv;
                            }

                            break;
                        }

                        case 7: // TryUpdate with a deliberately stale comparand: must ALWAYS fail (no phantom write)
                        {
                            long stale = (present ? cur : 0) ^ 0x5555_5555_5555L;
                            Assert.IsFalse(d.TryUpdate(k, nv, stale), $"TryUpdate matched a comparand no live value ever held for key {k}");
                            break;
                        }

                        case 8: // TryRemove (ordered): removes iff present and returns the exact stored value
                        {
                            bool removed = d.TryRemove(k, out long rv);
                            Assert.AreEqual(present, removed, $"TryRemove outcome disagrees with the reference for key {k}");
                            if (removed)
                            {
                                Assert.AreEqual(cur, rv, $"TryRemove handed back the wrong value for key {k}");
                                mine.Remove(k);
                            }

                            break;
                        }

                        case 9: // TryRemoveSwapBack (order-breaking, but this key's own membership+value are exact)
                        {
                            bool removed = d.TryRemoveSwapBack(k, out long rv);
                            Assert.AreEqual(present, removed, $"swap-back outcome disagrees with the reference for key {k}");
                            if (removed)
                            {
                                Assert.AreEqual(cur, rv, $"swap-back handed back the wrong value for key {k}");
                                mine.Remove(k);
                            }

                            break;
                        }

                        case 10: // read-only cross-check: both value paths and both membership paths agree with the reference
                        {
                            Assert.AreEqual(present, d.TryGetValue(k, out long gv), $"TryGetValue membership disagrees for key {k}");
                            if (present)
                            {
                                Assert.AreEqual(cur, gv, $"TryGetValue value disagrees for key {k}");
                            }

                            Assert.AreEqual(present, d.ContainsKey(k), $"ContainsKey disagrees for key {k}");
                            Assert.AreEqual(present, d.IndexOf(k) >= 0, $"index-path membership disagrees with the key path for key {k}");
                            break;
                        }

                        default: // AddRange of a short run of OWN keys: batch upsert, last write within the batch wins
                        {
                            int b0 = rng.Next(KeysPerThread - 4);
                            var batch = new KeyValuePair<int, long>[4];
                            for (int b = 0; b < 4; b++)
                            {
                                int bk = lo + b0 + b; // four distinct consecutive owned keys — no intra-batch dedup to reason about
                                long bv = Law(bk, gen++);
                                batch[b] = new KeyValuePair<int, long>(bk, bv);
                                mine[bk] = bv;
                            }

                            d.AddRange(batch);
                            break;
                        }
                    }

                    // THE per-operation linearization point: this thread owns k, and it has just applied its op to
                    // BOTH the reference and the collection, so the collection's view of k must equal the reference
                    // NOW — read both fresh (any AddRange touch to k is already reflected in the reference).
                    bool refPresent = mine.TryGetValue(k, out long refVal);
                    bool colPresent = d.TryGetValue(k, out long colVal);
                    Assert.AreEqual(refPresent, colPresent, $"post-op membership diverged from the reference for key {k}");
                    if (refPresent)
                    {
                        Assert.AreEqual(refVal, colVal, $"post-op value diverged from the reference for key {k}");
                    }
                }

                mirrors[id] = mine;
            });

            // Exact global oracle: the collection is precisely the disjoint union of the per-thread references.
            int expectedCount = mirrors.Sum(m => m.Count);
            Assert.AreEqual(expectedCount, d.Count, "final count is not the union of the per-thread references — a key leaked or vanished");
            foreach (Dictionary<int, long> m in mirrors)
            {
                foreach (KeyValuePair<int, long> kv in m)
                {
                    Assert.IsTrue(d.TryGetValue(kv.Key, out long v) && v == kv.Value, $"key {kv.Key} lost or corrupted versus its sequential reference");
                }
            }

            AssertFullyConsistent(d);
        }

        // ==========================================================================================================
        // 2. The golden oracle, barrier-phased: exact reference audit at every quiescent point between volleys.
        // ==========================================================================================================

        [TestMethod]
        public void Gun_RandomizedBarrierVolleys_PartitionedMirrors_ExactQuiescentAuditEveryRound()
        {
            // The same partitioned-reference discipline, but fired in Barrier-synchronized VOLLEYS. A Barrier's
            // post-phase action runs on exactly ONE thread while every participant is parked inside SignalAndWait —
            // a genuine frozen instant mid-battle — so it can audit the WHOLE collection against the summed
            // references EXACTLY: the total count equals the sum of the reference sizes, every Pairs entry obeys the
            // value law (no in-flight swap-back can mix a pair while everyone is parked), and the full round-trip
            // holds. Corruption that only ACCUMULATES across volleys (which a single final check could miss if a
            // later op happened to paper over it) is caught at the first quiescent point after it happens. Threads
            // carry their reference across rounds and keep drawing random key-addressed operations.
            const int KeysPerThread = 1_200;
            const int Rounds = 10;
            const int OpsPerRound = 2_500;
            int threads = HeavyThreads;

            var d = new ConcurrentOrderedCompactDict<int, long>();
            var mirrors = new Dictionary<int, long>[threads];
            for (int id = 0; id < threads; id++)
            {
                mirrors[id] = new Dictionary<int, long>();
            }

            long auditFailures = 0;
            using var barrier = new Barrier(threads, _ =>
            {
                // Post-phase quiescent audit: every participant is parked inside SignalAndWait, so this sees a frozen
                // collection and frozen references (the Barrier establishes the happens-before edge that publishes
                // both). This is where EVERY correctness assertion lives — never in the worker body — because an
                // assertion that threw mid-round would skip that thread's SignalAndWait and hang all the others until
                // the join ceiling; a throw HERE instead becomes a BarrierPostPhaseException on every waiter, so the
                // gun fails fast and cleanly. The reference (mine) is updated per the SPEC in the worker (from the
                // pre-op membership, not the collection's return value), so this comparison is a genuine oracle: if
                // the collection ever diverged from the sequential spec, mine and d disagree here.
                try
                {
                    int expected = mirrors.Sum(m => m.Count);
                    Assert.AreEqual(expected, d.Count, "count diverged from the summed references at a quiescent point");
                    foreach (Dictionary<int, long> m in mirrors)
                    {
                        foreach (KeyValuePair<int, long> kv in m)
                        {
                            Assert.IsTrue(d.TryGetValue(kv.Key, out long v) && v == kv.Value, $"key {kv.Key} diverged from its sequential reference at a quiescent point");
                        }
                    }

                    foreach (KeyValuePair<int, long> pair in d.Pairs)
                    {
                        Assert.AreEqual(pair.Key, LawKey(pair.Value), $"quiescent pair mixed: key {pair.Key} holds {pair.Value:X}");
                    }

                    AssertFullyConsistent(d);
                }
                catch
                {
                    // Count it too so a swallowed BarrierPostPhaseException wrapper can never hide an audit failure.
                    Interlocked.Increment(ref auditFailures);
                    throw;
                }
            });

            FireGun(threads, id =>
            {
                int lo = id * KeysPerThread;
                Dictionary<int, long> mine = mirrors[id];
                var rng = new System.Random(4_000 + id);
                int gen = 1;

                for (int round = 0; round < Rounds; round++)
                {
                    // ASSERT-FREE worker: apply the op to the collection and advance the reference per the SPEC
                    // (keyed off the pre-op membership, since nobody else writes this key), then park on the barrier.
                    // All checking is deferred to the quiescent post-phase above so a divergence cannot hang the gun.
                    for (int op = 0; op < OpsPerRound; op++)
                    {
                        int k = lo + rng.Next(KeysPerThread);
                        long nv = Law(k, gen++);
                        bool present = mine.TryGetValue(k, out long cur);

                        switch (rng.Next(7))
                        {
                            case 0: // TryAdd → adds iff absent
                                d.TryAdd(k, nv);
                                if (!present)
                                {
                                    mine[k] = nv;
                                }

                                break;

                            case 1: // SetByKey → upsert
                                d.SetByKey(k, nv);
                                mine[k] = nv;
                                break;

                            case 2: // GetOrAdd → adds iff absent, existing value survives otherwise
                                d.GetOrAdd(k, nv);
                                if (!present)
                                {
                                    mine[k] = nv;
                                }

                                break;

                            case 3: // AddOrUpdate → key holds nv either way
                                d.AddOrUpdate(k, nv, (_, __) => nv);
                                mine[k] = nv;
                                break;

                            case 4: // TryRemove → removes iff present
                                d.TryRemove(k, out _);
                                if (present)
                                {
                                    mine.Remove(k);
                                }

                                break;

                            case 5: // TryRemoveSwapBack → removes iff present (relocates some other partition's tail)
                                d.TryRemoveSwapBack(k, out _);
                                if (present)
                                {
                                    mine.Remove(k);
                                }

                                break;

                            default: // TryUpdate CAS with the matching comparand → succeeds iff present
                                d.TryUpdate(k, nv, present ? cur : 0);
                                if (present)
                                {
                                    mine[k] = nv;
                                }

                                break;
                        }
                    }

                    barrier.SignalAndWait(); // volley over; the post-phase audit runs while everyone is parked here
                }
            });

            Assert.AreEqual(0, Interlocked.Read(ref auditFailures), "a quiescent audit failed mid-battle");

            // Exact final oracle, per key, against every reference.
            int expectedFinal = mirrors.Sum(m => m.Count);
            Assert.AreEqual(expectedFinal, d.Count, "final count is not the union of the per-thread references");
            foreach (Dictionary<int, long> m in mirrors)
            {
                foreach (KeyValuePair<int, long> kv in m)
                {
                    Assert.IsTrue(d.TryGetValue(kv.Key, out long v) && v == kv.Value, $"key {kv.Key} diverged from its reference");
                }
            }

            AssertFullyConsistent(d);
        }

        // ==========================================================================================================
        // 3. Shared space, random ORDER-PRESERVING surface: the exact pair law holds under every interleaving.
        // ==========================================================================================================

        [TestMethod]
        public void Gun_RandomizedOrderPreservingChaos_SharedSpace_ExactPairLaw()
        {
            // A SHARED key space (no partitioning, so no exact membership oracle) hammered by a fully random mix of
            // ORDER-PRESERVING operations — TryAdd, SetByKey, GetOrAdd, AddOrUpdate, TryUpdate, ordered TryRemove,
            // interior RemoveAt, a pure-predicate RemoveWhere, and AddRange — while dedicated readers sweep every
            // single-snapshot pair surface. None of these ops relocates a slot in place: appends publish both slots
            // before the count, interior removes compact into FRESH arrays, and value replaces keep the slot's key
            // (writing another law-valid value for the SAME key). Therefore Pairs and any captured Snapshot must
            // NEVER expose a mixed (key, value): with every value written as Law(itsKey, gen), the equality
            // LawKey(value) == key is an exact, interleaving-independent invariant.
            //
            // TryRemoveSwapBack is DELIBERATELY excluded here — it is the one operation allowed to transiently mix a
            // slot's key and value — and so is the index-addressed value setter (SetAt), whose target key is a
            // moving target under concurrent reindexing. Both appear in the maximal-chaos scenario below under the
            // weaker checks their contracts permit.
            const int Universe = 20_000;
            const int WriterOps = 25_000;
            int threads = HeavyThreads;
            int writers = System.Math.Max(1, threads * 3 / 4); // a quarter of the gun are dedicated pair auditors

            var d = new ConcurrentOrderedCompactDict<int, long>();
            for (int k = 0; k < Universe; k += 2)
            {
                d.Add(k, Law(k, 0)); // seed the evens so readers have a populated structure from the first instant
            }

            long writersDone = 0;
            FireGun(threads, id =>
            {
                if (id < writers)
                {
                    var rng = new System.Random(6_000 + id);
                    int gen = 1;
                    try
                    {
                        for (int op = 0; op < WriterOps; op++)
                        {
                            int k = rng.Next(Universe);
                            long nv = Law(k, gen++);
                            switch (rng.Next(9))
                            {
                                case 0:
                                    d.TryAdd(k, nv);
                                    break;
                                case 1:
                                    d.SetByKey(k, nv); // in-place value replace: keeps the key, writes a law-valid value
                                    break;
                                case 2:
                                    d.GetOrAdd(k, nv);
                                    break;
                                case 3:
                                    d.AddOrUpdate(k, nv, (key, _) => Law(key, gen)); // update writes a law value for the SAME key
                                    break;
                                case 4:
                                    if (d.TryGetValue(k, out long cur))
                                    {
                                        d.TryUpdate(k, nv, cur); // losing the CAS is fine; it never writes a foreign value
                                    }

                                    break;
                                case 5:
                                    d.TryRemove(k, out _); // ordered remove → fresh-array compaction
                                    break;
                                case 6:
                                    // Interior RemoveAt by a (possibly stale) index — legal to miss, never to corrupt.
                                    try
                                    {
                                        d.RemoveAt(rng.Next(System.Math.Max(1, d.Count)));
                                    }
                                    catch (ArgumentOutOfRangeException)
                                    {
                                        // The count shrank under us between the read and the call — a legal race, not a fault.
                                    }

                                    break;
                                case 7:
                                    // A PURE predicate (no mutation → never trips the reentrancy guard); removes a thin residue class.
                                    if ((op & 0x3FF) == 0)
                                    {
                                        d.RemoveWhere((key, _) => (key % 997) == (op % 997));
                                    }

                                    break;
                                default:
                                {
                                    // AddRange of a short fresh run — precomputed array (not a generator), so the source
                                    // enumeration performs no write and the reentrancy guard is not engaged.
                                    int b0 = rng.Next(Universe - 4);
                                    var batch = new KeyValuePair<int, long>[4];
                                    for (int b = 0; b < 4; b++)
                                    {
                                        batch[b] = new KeyValuePair<int, long>(b0 + b, Law(b0 + b, gen));
                                    }

                                    d.AddRange(batch);
                                    break;
                                }
                            }
                        }
                    }
                    finally
                    {
                        Interlocked.Increment(ref writersDone);
                    }
                }
                else
                {
                    // Pair auditors: sweep both single-snapshot surfaces continuously until the writers are done.
                    while (Interlocked.Read(ref writersDone) < writers)
                    {
                        foreach (KeyValuePair<int, long> pair in d.Pairs)
                        {
                            Assert.AreEqual(pair.Key, LawKey(pair.Value), $"Pairs exposed a mixed pair under order-preserving churn: ({pair.Key}, {pair.Value:X})");
                        }

                        ConcurrentOrderedCompactDict<int, long>.ValuesView view = d.Snapshot();
                        for (int i = 0; i < view.Count; i++)
                        {
                            Assert.AreEqual(view.GetKeyAt(i), LawKey(view[i]), "Snapshot view exposed a mixed pair under order-preserving churn");
                        }
                    }
                }
            });

            // Quiescent: every surviving value still obeys the law and the structure is fully self-consistent.
            foreach (KeyValuePair<int, long> pair in d.Pairs)
            {
                Assert.AreEqual(pair.Key, LawKey(pair.Value), "a surviving pair is mixed after the storm");
            }

            AssertFullyConsistent(d);
        }

        // ==========================================================================================================
        // 4. Shared space, the ENTIRE random surface (swap-back + Clear included): no corruption, no crash.
        // ==========================================================================================================

        [TestMethod]
        public void Gun_RandomizedFullSurfaceChaos_WithSwapBackAndClear_NeverCorruptsOrCrashes()
        {
            // The maximal storm: the WHOLE mutating and reading surface, chosen at random by every thread over a
            // shared key space, with no partitioning and no exact membership oracle — including the order-breaking
            // TryRemoveSwapBack and periodic Clear. What must hold under EVERY interleaving is asserted:
            //   * no operation faults except the documented races, which are swallowed as legal (a duplicate-key
            //     Add, an out-of-range RemoveAt/TryGetAt against a shrinking count);
            //   * no read ever yields a value that is not a law-shaped datum for an IN-RANGE key — a torn or
            //     cross-contaminated value would decode to a key outside [0, Universe);
            //   * every operation, and the whole gun, terminates (the join ceiling is the deadlock detector).
            // Because swap-back may transiently mix a slot's key and value (and a captured Snapshot shares the live
            // arrays it mutates in place), the EXACT pair law and duplicate-freedom are asserted only at the FINAL
            // quiescent point, never on a live surface here — that is precisely the contract boundary scenario 3
            // above lives inside.
            const int Universe = 16_000;
            const int WriterOps = 25_000;
            int threads = HeavyThreads;
            int writers = System.Math.Max(1, threads * 3 / 4);

            var d = new ConcurrentOrderedCompactDict<int, long>();
            for (int k = 0; k < Universe; k += 2)
            {
                d.Add(k, Law(k, 0));
            }

            // Weak, interleaving-independent value check: a clean value decodes to an in-range key; a torn or
            // cross-key value almost certainly would not.
            static void AssertLawShaped(long v)
                => Assert.IsTrue((uint)LawKey(v) < Universe, $"a read returned a non-law-shaped value 0x{v:X16} (decodes to key {LawKey(v)})");

            long writersDone = 0;
            FireGun(threads, id =>
            {
                var rng = new System.Random(8_000 + id);
                if (id < writers)
                {
                    int gen = 1;
                    try
                    {
                        for (int op = 0; op < WriterOps; op++)
                        {
                            int k = rng.Next(Universe);
                            long nv = Law(k, gen++);
                            switch (rng.Next(12))
                            {
                                case 0:
                                    d.TryAdd(k, nv);
                                    break;
                                case 1:
                                    try
                                    {
                                        d.Add(k, nv); // may race-lose to a concurrent add of the same key
                                    }
                                    catch (ArgumentException)
                                    {
                                        // Duplicate key under the race — the documented, legal outcome of Add.
                                    }

                                    break;
                                case 2:
                                    d.SetByKey(k, nv);
                                    break;
                                case 3:
                                    d.GetOrAdd(k, _ => nv);
                                    break;
                                case 4:
                                    d.AddOrUpdate(k, nv, (key, _) => Law(key, gen));
                                    break;
                                case 5:
                                    if (d.TryGetValue(k, out long cur))
                                    {
                                        d.TryUpdate(k, nv, cur);
                                    }

                                    break;
                                case 6:
                                    d.TryRemove(k, out _);
                                    break;
                                case 7:
                                    d.TryRemoveSwapBack(k, out _); // the order-breaking, transiently-mixing removal
                                    break;
                                case 8:
                                    try
                                    {
                                        d.RemoveAt(rng.Next(System.Math.Max(1, d.Count)));
                                    }
                                    catch (ArgumentOutOfRangeException)
                                    {
                                        // Stale index against a shrinking count — a legal race.
                                    }

                                    break;
                                case 9:
                                    if ((op & 0x7FF) == 0)
                                    {
                                        d.RemoveWhere((key, _) => (key % 991) == (op % 991)); // pure predicate
                                    }

                                    break;
                                case 10:
                                    if ((op & 0x1FFF) == 0)
                                    {
                                        d.Clear(); // rare full wipe; whatever repopulates still obeys the law
                                    }

                                    break;
                                default:
                                {
                                    int b0 = rng.Next(Universe - 4);
                                    var batch = new KeyValuePair<int, long>[4];
                                    for (int b = 0; b < 4; b++)
                                    {
                                        batch[b] = new KeyValuePair<int, long>(b0 + b, Law(b0 + b, gen));
                                    }

                                    d.AddRange(batch);
                                    break;
                                }
                            }
                        }
                    }
                    finally
                    {
                        Interlocked.Increment(ref writersDone);
                    }
                }
                else
                {
                    // Readers: hammer every surface with the weak law (swap-back forbids exact pairing on a live
                    // surface). Any decode to an out-of-range key is a torn/contaminated read.
                    while (Interlocked.Read(ref writersDone) < writers)
                    {
                        int k = rng.Next(Universe);
                        if (d.TryGetValue(k, out long byKey))
                        {
                            Assert.AreEqual(k, LawKey(byKey), $"key {k} exposed another key's value 0x{byKey:X16}");
                        }

                        if (d.TryGetAt(rng.Next(System.Math.Max(1, d.Count)), out long byIndex))
                        {
                            AssertLawShaped(byIndex);
                        }

                        foreach (long v in d)
                        {
                            AssertLawShaped(v);
                        }

                        ConcurrentOrderedCompactDict<int, long>.ValuesView view = d.Snapshot();
                        for (int i = 0; i < view.Count; i++)
                        {
                            AssertLawShaped(view[i]);
                        }

                        _ = d.ToArray();
                        _ = d.Keys;
                        Thread.Yield(); // widen preemption diversity
                    }
                }
            });

            // Final quiescent point: swap-back is finished, so the strong invariants must now hold exactly — no
            // mixed pair, no duplicate key, full round-trip.
            var seen = new HashSet<int>();
            foreach (KeyValuePair<int, long> pair in d.Pairs)
            {
                Assert.AreEqual(pair.Key, LawKey(pair.Value), $"a surviving pair is mixed after the storm: ({pair.Key}, {pair.Value:X})");
                Assert.IsTrue(seen.Add(pair.Key), $"key {pair.Key} survived twice — a slot was structurally duplicated");
            }

            AssertFullyConsistent(d);

            // And the instance is fully usable afterwards.
            d.Clear();
            Assert.AreEqual(0, d.Count);
            Assert.IsTrue(d.IsEmpty);
            d.Add(1, Law(1, 0));
            Assert.AreEqual(1, d.Count);
        }
    }
}
